CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY, name TEXT NOT NULL, settings TEXT NOT NULL, virtual_time TEXT NOT NULL, seed INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(user_id TEXT REFERENCES users(id), tenant_id TEXT REFERENCES tenants(id), role TEXT NOT NULL CHECK(role IN ('owner','manager','csr','finance','viewer')), PRIMARY KEY(user_id,tenant_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), tenant_id TEXT REFERENCES tenants(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stores(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,platform TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,contact TEXT NOT NULL,consent_source TEXT NOT NULL,consent_at TEXT,opt_out_at TEXT, UNIQUE(tenant_id,contact));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),sku TEXT NOT NULL,name TEXT NOT NULL,price INTEGER NOT NULL,cogs INTEGER NOT NULL,weight_g INTEGER NOT NULL, UNIQUE(tenant_id,sku));
CREATE TABLE IF NOT EXISTS couriers(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,code TEXT NOT NULL,color TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>=0),max_weight INTEGER NOT NULL,max_cod INTEGER NOT NULL,zones TEXT NOT NULL,forward INTEGER NOT NULL CHECK(forward>=0),reverse INTEGER CHECK(reverse>=0),cod_fee INTEGER NOT NULL CHECK(cod_fee>=0),rto_bp INTEGER NOT NULL,late_bp INTEGER NOT NULL,sla_days INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),external_id TEXT NOT NULL,city TEXT NOT NULL,address TEXT NOT NULL,address_quality INTEGER NOT NULL CHECK(address_quality BETWEEN 0 AND 100),cod INTEGER NOT NULL CHECK(cod>0),cogs INTEGER NOT NULL CHECK(cogs>=0),weight_g INTEGER NOT NULL CHECK(weight_g>0),packaging INTEGER NOT NULL,marketing INTEGER NOT NULL,service_cost INTEGER NOT NULL DEFAULT 0,refund INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN ('imported','verification_pending','confirmed','ready_to_ship','booked_simulated','in_transit','out_for_delivery','NDR','reattempt','RTO_initiated','returned','delivered','hold_review','cancelled_before_ship','lost_damaged_dispute')),verification TEXT NOT NULL,risk_score INTEGER NOT NULL CHECK(risk_score BETWEEN 0 AND 100),risk_reasons TEXT NOT NULL,courier_id TEXT REFERENCES couriers(id),forward INTEGER NOT NULL DEFAULT 0,reverse INTEGER NOT NULL DEFAULT 0,cod_fee INTEGER NOT NULL DEFAULT 0,expected_cost INTEGER NOT NULL DEFAULT 0,actual_cost INTEGER NOT NULL DEFAULT 0,revenue INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,dispatch_at TEXT,version INTEGER NOT NULL DEFAULT 0,simulated INTEGER NOT NULL DEFAULT 1,seed_version TEXT NOT NULL DEFAULT 'PG-1', UNIQUE(tenant_id,external_id));
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),qty INTEGER NOT NULL CHECK(qty>0),unit_price INTEGER NOT NULL,cogs INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),order_id TEXT REFERENCES orders(id),kind TEXT NOT NULL,from_state TEXT,to_state TEXT,payload TEXT NOT NULL,occurred_at TEXT NOT NULL,ingested_at TEXT NOT NULL,source TEXT NOT NULL DEFAULT 'simulation', UNIQUE(tenant_id,source,id));
CREATE TABLE IF NOT EXISTS agent_runs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),order_id TEXT REFERENCES orders(id),agent TEXT NOT NULL,input TEXT NOT NULL,output TEXT NOT NULL,rule_version TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,correlation_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL,retry_count INTEGER NOT NULL DEFAULT 0,locked_until TEXT,last_error TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS allocations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),proposal TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,approved_by TEXT);
CREATE TABLE IF NOT EXISTS statements(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),order_id TEXT NOT NULL REFERENCES orders(id),booking_ref TEXT NOT NULL,expected INTEGER NOT NULL,actual INTEGER,status TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL,resolved_by TEXT, UNIQUE(tenant_id,booking_ref));
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT,payload TEXT NOT NULL,created_at TEXT NOT NULL,request_id TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END;
CREATE TABLE IF NOT EXISTS idempotency(tenant_id TEXT NOT NULL REFERENCES tenants(id),key TEXT NOT NULL,command TEXT NOT NULL,payload_hash TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(tenant_id,key));
CREATE INDEX IF NOT EXISTS orders_tenant_status ON orders(tenant_id,status,created_at DESC,id);
CREATE INDEX IF NOT EXISTS orders_tenant_city ON orders(tenant_id,city,created_at);
CREATE INDEX IF NOT EXISTS events_order ON events(tenant_id,order_id,occurred_at);
CREATE INDEX IF NOT EXISTS traces_tenant ON agent_runs(tenant_id,created_at DESC);
CREATE INDEX IF NOT EXISTS audit_tenant ON audit(tenant_id,created_at DESC);
CREATE INDEX IF NOT EXISTS statements_tenant ON statements(tenant_id,status);
CREATE INDEX IF NOT EXISTS dispatch_capacity ON orders(tenant_id,courier_id,dispatch_at,status);
